"""Generate parameters/layout.json for the 4-channel TPA3255 board.

All positions ESTIMATED from the three listing photos in references/ (no scale
in the photos; board size 108 x 94 mm assumed, see requirements.md).
Axes: x along the 108 mm edge, y = 0 at the input (white XH) edge, y = 94 at
the speaker-terminal edge, z up from the PCB bottom.
"""
import json
import pathlib

T = 1.6
lay = {
    "_comment": "Generated by design/gen_layout.py; edit that script, not this file. All positions estimated.",
    "board": {"l": 108, "w": 94},
    "pcb": {"t": T, "r": 0},
    "holes": [{"x": x, "y": y, "d": 3.2} for x in (4, 104) for y in (4, 90)],
    "packages": {
        "0603": {"l": 1.6, "w": 0.8, "h": 0.45, "kind": "passive"},
        "0805": {"l": 2.0, "w": 1.25, "h": 0.6, "kind": "passive"},
        "SOIC8": {"l": 4.9, "w": 3.9, "h": 1.5, "kind": "tssop", "pins_side": 4},
        "SOT23": {"l": 2.9, "w": 1.3, "h": 1.1, "kind": "sot23"},
        "XH3": {"l": 9.9, "w": 5.75, "h": 7.0, "kind": "jst"},
        "XH2": {"l": 7.4, "w": 5.75, "h": 7.0, "kind": "jst"},
    },
    "parts": [], "blocks": [], "cyls": [], "cuts": [],
}
P, B, C = lay["parts"], lay["blocks"], lay["cyls"]

# --- power side (y 68..94): per channel 2 inductors, 2 film caps, 1 screw terminal
inductor, film, term = (9.5, 9.5, 8.0), (7.2, 5.0, 9.5), (10.2, 8.0, 10.0)
channels = {"CH4": (10.5, 20.5), "CH3": (31.5, 41.5), "CH2": (68.0, 78.0), "CH1": (89.0, 99.0)}
for ch, xs in channels.items():
    for k, x in enumerate(xs):
        B.append({"ref": f"{ch}_L{k + 1}", "x": x, "y": 73.0, "l": inductor[0], "w": inductor[1], "h": inductor[2], "z0": T})
        B.append({"ref": f"{ch}_Cfilm{k + 1}", "x": x, "y": 81.5, "l": film[0], "w": film[1], "h": film[2], "z0": T})
    B.append({"ref": f"{ch}_terminal", "x": sum(xs) / 2, "y": 90.0, "l": term[0], "w": term[1], "h": term[2], "z0": T})
B.append({"ref": "PWR_terminal", "x": 54.0, "y": 90.0, "l": term[0], "w": term[1], "h": term[2], "z0": T})
for k, (x, y) in enumerate(((50.5, 72.5), (59.0, 72.5), (50.5, 81.0), (59.0, 81.0))):
    C.append({"ref": f"C_bulk{k + 1}", "x": x, "y": y, "d": 8.0, "h": 12.0, "z0": T})

# --- heatsink on the two TPA3255 chips (y 38..66), fins = grooves in the front face
for k, x in enumerate((35.0, 73.0)):
    B.append({"ref": f"U_TPA3255_{k + 1}", "x": x, "y": 52.0, "l": 14.0, "w": 6.1, "h": 1.2, "z0": T})
hs = {"x0": 10.0, "x1": 98.0, "y0": 38.0, "y1": 66.0, "z0": T + 1.2, "h": 22.0}
B.append({"ref": "Heatsink", "x": (hs["x0"] + hs["x1"]) / 2, "y": (hs["y0"] + hs["y1"]) / 2,
          "l": hs["x1"] - hs["x0"], "w": hs["y1"] - hs["y0"], "h": hs["h"], "z0": hs["z0"]})
for k in range(4):  # 4 grooves -> 5 fins, groove 2.0 tall, 7 deep, from the x1 end through the whole length
    zc = hs["z0"] + 4.0 + 4.0 * k
    lay["cuts"].append({"ref": f"Fin_groove{k + 1}", "axis": "x", "at": hs["x1"],
                        "a": hs["y0"] + 3.5, "b": zc, "l": 7.0, "w": 2.0, "depth": hs["x1"] - hs["x0"]})

# --- input side (y 0..36): XH inputs, per channel op-amp + caps + passives, buck regulator in the middle
inputs = {"IN4": 12.0, "IN3": 33.0, "MUTE": 54.0, "IN2": 75.0, "IN1": 96.0}
for ref, x in inputs.items():
    P.append({"ref": f"J_{ref}", "pkg": "XH2" if ref == "MUTE" else "XH3", "x": x, "y": 4.5})
for ref, x in ((k, v) for k, v in inputs.items() if k != "MUTE"):
    P.append({"ref": f"U_{ref}_opamp", "pkg": "SOIC8", "x": x, "y": 20.0})
    P.append({"ref": f"Q_{ref}", "pkg": "SOT23", "x": x - 6.5, "y": 14.0})
    for k, dx in enumerate((-4.0, -1.5, 1.5, 4.0)):
        P.append({"ref": f"R_{ref}_{k + 1}", "pkg": "0603", "x": x + dx, "y": 26.5})
    for k, dy in enumerate((16.5, 20.0, 23.5)):
        P.append({"ref": f"C_{ref}_{k + 1}", "pkg": "0603", "x": x + 6.5, "y": dy, "rot": 90})
    P.append({"ref": f"C_{ref}_dec", "pkg": "0805", "x": x, "y": 12.0})
    for k, (dx, dy) in enumerate(((-5.0, 31.5), (5.0, 31.5))):
        C.append({"ref": f"C_{ref}_e{k + 1}", "x": x + dx, "y": dy, "d": 5.0, "h": 5.5, "z0": T})
B.append({"ref": "L_buck_XL7005", "x": 54.0, "y": 24.0, "l": 5.8, "w": 5.2, "h": 4.5, "z0": T})
B.append({"ref": "U_LM7812_TO252", "x": 54.0, "y": 14.5, "l": 6.6, "w": 6.1, "h": 2.3, "z0": T})
for k, (x, y) in enumerate(((45.5, 30.0), (62.5, 30.0), (45.5, 21.0))):
    C.append({"ref": f"C_buck{k + 1}", "x": x, "y": y, "d": 6.3, "h": 7.7, "z0": T})

out = pathlib.Path(__file__).parents[1] / "parameters" / "layout.json"
out.write_text(json.dumps(lay, indent=1) + "\n")
print("wrote", out, len(P), "parts,", len(B), "blocks,", len(C), "cyls,", len(lay["cuts"]), "cuts")
